/**
 * Static map datasets generated by scripts/build-map-data.mjs into public/map-data.
 * Kept separate from greenestApi.ts, which talks to the FastAPI backend.
 */
import type { FeatureCollection, Polygon } from 'geojson'
import type { AreaProperties } from '@/types/greenest'

export type OverviewData = {
  areas: FeatureCollection<Polygon, AreaProperties>
}

async function getStatic<T>(file: string, signal?: AbortSignal): Promise<T> {
  const response = await fetch(`/map-data/${file}`, { signal })
  if (!response.ok) {
    throw new Error(
      `Could not load ${file} (${response.status}). Run "node scripts/build-map-data.mjs".`,
    )
  }
  return response.json() as Promise<T>
}

export async function fetchOverviewData(
  signal?: AbortSignal,
): Promise<OverviewData> {
  // The street layers, roughness too, come from the backend (hooks/useOverlays.ts), which names their streets.
  const areas = await getStatic<OverviewData['areas']>('areas.geojson', signal)
  return { areas }
}
